defineProps<{summary:{month:string;totals:{currency:string;amount:string}[];unresolved:number};transactions:{data:Transaction[];prev_page_url:string|null;next_page_url:string|null};needsReview:Transaction[]}>();
usePoll(6000, {only:['transactions','needsReview','summary']});
